using System.Text.Json.Serialization;
namespace TwinTrack.Models;
public sealed class FolderModel { [JsonPropertyName("id")] public string Id {get;set;}=Guid.NewGuid().ToString("N"); [JsonPropertyName("name")] public string Name {get;set;}=""; [JsonPropertyName("path")] public string Path {get;set;}=""; [JsonPropertyName("fileCount")] public int FileCount {get;set;} [JsonPropertyName("hasResults")] public bool HasResults {get;set;} }
public sealed class FileItem { [JsonPropertyName("name")] public string Name {get;set;}=""; [JsonPropertyName("size")] public long Size {get;set;} [JsonPropertyName("fullPath")] public string FullPath {get;set;}=""; [JsonPropertyName("relPath")] public string RelPath {get;set;}=""; [JsonPropertyName("dir")] public string Dir {get;set;}=""; [JsonPropertyName("quickSig")] public string? QuickSig {get;set;} [JsonPropertyName("contentHash")] public string? ContentHash {get;set;} [JsonPropertyName("folderId")] public string FolderId {get;set;}=""; [JsonIgnore] public string Artist {get;set;}="—"; [JsonIgnore] public string Title {get;set;}=""; }
public sealed class AppState { [JsonPropertyName("version")] public int Version {get;set;}=9; [JsonPropertyName("folders")] public List<FolderModel> Folders {get;set;}=new(); [JsonPropertyName("trash")] public List<FileItem> Trash {get;set;}=new(); }
public sealed class ResultSummary { [JsonPropertyName("duplicateCount")] public int DuplicateCount {get;set;} [JsonPropertyName("groupCount")] public int GroupCount {get;set;} [JsonPropertyName("duplicateBytes")] public long DuplicateBytes {get;set;} }
public sealed class ScanResult { [JsonPropertyName("folderId")] public string FolderId {get;set;}=""; [JsonPropertyName("folderPath")] public string FolderPath {get;set;}=""; [JsonPropertyName("fileCount")] public int FileCount {get;set;} [JsonPropertyName("groups")] public List<List<FileItem>> Groups {get;set;}=new(); [JsonPropertyName("summary")] public ResultSummary Summary {get;set;}=new(); [JsonPropertyName("scannedAt")] public string ScannedAt {get;set;}=DateTime.UtcNow.ToString("O"); }
public sealed record ScanProgress(double Percent,string Text,string Phase,bool Paused=false);
